  select.appendChild(allOpt);

  for (const d of dealers) {
    const opt = document.createElement("option");
    opt.value = d;
    opt.textContent = d;
    select.appendChild(opt);
  }

  select.value = dealers.includes(prev) || prev === "all" ? prev : "all";
