async function downscaleImage(fileOrBlob, maxDim = 1600, quality = 0.8) {
  const bitmap = await createImageBitmap(fileOrBlob);
  let { width, height } = bitmap;

  if (width > height && width > maxDim) {
    height = Math.round((height * maxDim) / width);
    width = maxDim;
  } else if (height >= width && height > maxDim) {
    width = Math.round((width * maxDim) / height);
    height = maxDim;
  }

  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;

  const ctx = canvas.getContext("2d", { alpha: false });
  ctx.drawImage(bitmap, 0, 0, width, height);

  const blob = await new Promise((resolve) =>
    canvas.toBlob(resolve, "image/jpeg", quality)
  );

  if (!blob) throw new Error("Downscale failed");
  return blob;
}

async function uploadProofPhoto({ sb, empId, logId, file, roNumber = null }) {
  const uid = await requireUserId();
  if (!uid) throw new Error("Sign in required");

  const uploadBlob = await downscaleImage(file);
  const ext = "jpg";
  const path = `${uid}/${empId}/${logId}.${ext}`;

  const { error } = await sb.storage
    .from("proofs")
    .upload(path, uploadBlob, {
      contentType: "image/jpeg",
      upsert: true,
      // Defense-in-depth alongside the client-side URL cache: lets any CDN/
      // edge layer between Supabase and the client cache the bytes for a
      // while too. Kept moderate (1 hour, not "immutable forever") since a
      // retaken photo overwrites the same path with upsert:true — too long
      // a value would risk serving stale bytes after a retake.
      cacheControl: "3600",
    });

  if (error) throw error;
  const { error: updateErr } = await sb.from("work_logs").update({ photo_path: path }).eq("id", logId);
  if (updateErr) throw updateErr;
  return { path, dealer: null };
}

